import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, texture, mix, vec3 } from 'three/tsl';
import { Group, Mesh, PlaneGeometry, Color } from 'three';

export default function createNode(config, ctx) {
  const group = new Group();
  group.position.set(0, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Load the brushed-metal texture
  const metalTexture = ctx.textureLoader.loadTexture(config.imageUrl);

  // Create the plane geometry (card-like proportions for label)
  const geometry = new PlaneGeometry(2.4, 0.5);

  // TSL-based material with engineered gradient and subtle grain
  const uvNode = uv();

  // Sample the brushed-metal texture for surface detail
  const metalSample = texture(metalTexture, uvNode);

  // Engineered vertical gradient: surface (#0b0b10) to ink (#16161d) with subtle lift
  const gradientY = uvNode.y;
  const surfaceColor = new Color('#0b0b10');
  const inkColor = new Color('#16161d');
  const gradientMix = mix(vec3(...surfaceColor.toArray()), vec3(...inkColor.toArray()), gradientY);

  // Blend gradient with metal texture for subtle grain and surface detail
  const blendedColor = mix(gradientMix, metalSample.rgb, 0.15);

  // Create material with the blended color
  const material = new MeshBasicNodeMaterial({
    colorNode: blendedColor,
    transparent: true,
    opacity: 0.95,
  });

  // Create the plane mesh
  const plane = new Mesh(geometry, material);
  group.add(plane);

  // Create text label: "Collection 2"
  const textContent = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const labelText = textContent.find((item) => item.role === 'headline')?.text ?? 'Collection 2';

  // Render text with headline sizing (39px → ~0.34 scene units at typical DPI)
  const textMesh = ctx.fontAtlas.createText(labelText, {
    fontSize: 0.3,
    color: '#e8ecf2', // paper color for contrast
    align: 'center',
    letterSpacingPx: 1.5,
  });

  // Position text centered on the plane
  textMesh.position.set(0, 0, 0.01); // Slight z offset to prevent z-fighting
  group.add(textMesh);

  // Cleanup function
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    metalTexture.dispose();
  };

  // Event handlers (none specified)
  group.userData.handlers = {};

  return group;
}
